// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    function setUp() public {
        c = new DnGmxBatchingManager();
    }
    function testFuzz_property(address nonOwner, address newOwner) public {
        vm.assume(nonOwner != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(nonOwner != address(this));
        vm.assume(nonOwner != c.owner());
        vm.assume(newOwner != c.owner());
        address originalOwner = c.owner();
        vm.prank(nonOwner);
        bool ok;
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }
        assertTrue(!ok || c.owner() == originalOwner);
    }
}
